// Per-run cost (ms) of each pipeline stage, in fixed order.
const COST = { style: 0.2, layout: 3.0, paint: 1.5, composite: 0.5 };
const ORDER = ['style', 'layout', 'paint', 'composite'];

// A path re-runs from its entry stage through Composite (always last).
function pathCost(entry) {
  const start = ORDER.indexOf(entry);
  let sum = 0;
  for (let i = start; i < ORDER.length; i++) sum += COST[ORDER[i]];
  return sum;
}

const RUNS = 50; // re-animate the card 50 times in one frame
// width animation enters the pipeline at Layout:
const widthEntry = 'layout';
// transform animation enters the pipeline at Composite:
const transformEntry = 'composite';

const widthTotal = pathCost(widthEntry) * RUNS;
const transformTotal = pathCost(transformEntry) * RUNS;
// The cheaper path is the one to ship — name it the winner.
const winner = transformTotal < widthTotal ? 'transform' : 'width';

console.log('width=' + widthTotal.toFixed(1) + 'ms transform=' + transformTotal.toFixed(1) + 'ms winner=' + winner);
